    void fmt;
  }

  function roundRect(x, y, wid, hei, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + wid, y, x + wid, y + hei, r);
    ctx.arcTo(x + wid, y + hei, x, y + hei, r);
    ctx.arcTo(x, y + hei, x, y, r);
    ctx.arcTo(x, y, x + wid, y, r);
